      "status": "success",
      "details": {
        "response": "success",
        "message": "Product created",
        "data": [
          {
            "product_information_id": [
              192044
            ]
          },
          {
            "product_dimensions_info": {
              "ASYNC-BULK-0001-ff1aabc450": 191979
            }
          }
        ]
      }
    },
